  // memory
  logic [7:0] mem [15:0];
  integer state = `RDY;
  integer cc = 0;
  integer addr = 0;
  integer branch_pred = 0;
  integer wrong_attmpt = 0;
  reg is_ram = 1;

  task increment_pc();
    pc = pc + 2;
  endtask

  task load_safeROM();
    // $display("loading safe rom, safely...");
    $readmemh("flag.hex",safe_rom);
  endtask

  task load_ram();
    // $display("loading user controlled memory...");
