        end
      end
      `RDTM: begin
        regfile[ram[pc][5:4]] <= tck;
        increment_pc();
      end
      `MOVFU: begin
        if ((cache_rdy[0] == 1) && (cache[0] == ram[pc+1])) begin
           regfile[ram[pc][5:4]] <= cache_v[0];
