           increment_pc();
        end else if ((cache_rdy[1] == 2) && (cache[1] == safe_rom[pc+1])) begin
           regfile[ram[pc][5:4]] <= cache_v[1];
           increment_pc();
        end else begin
           state <= `MSTAGE_1;
           addr <= ram[pc+1];
           is_ram <= 0;
        end
        end
        increment_pc();
