import re

filename = '/home/ctfplayer/ctf_files/ncore_tb.v'
with open(filename) as f:
    code = f.read()

# Define signals to track, and possible storage
track_signals = ['key', 'emode', 'wrong_attmpt']
storage = ['ram', 'register', 'cache', 'mem', 'memory', 'out', 'output', 'dump']

results = {name: set() for name in track_signals}

# Find all regs and wires
lines = code.splitlines()
regs = set()
wires = set()
for l in lines:
    l = l.strip()
    m = re.match(r'(reg|wire) (\[.*?\] )?(\w+)', l)
    if m:
        kind, _, name = m.groups()
        if kind == 'reg':
            regs.add(name)
        else:
            wires.add(name)

# Scan for assignments
for sig in track_signals:
    pattern = re.compile(r'\b' + re.escape(sig) + r'\b')
    for i,line in enumerate(lines):
        if pattern.search(line):
            cmt = ' // ' + line if '//' not in line else ''
            # check for assignment or move
            if '<=' in line or '=' in line:
                # is it assigned to something? track lhs/rhs
                parts = re.split(r'(<=|=)', line)
                if len(parts) >= 3:
                    lhs, op, rhs = parts[0].strip(), parts[1], parts[2].strip()
                    if sig in (lhs + rhs):
                        # look for anything storage-like on lhs/rhs
                        for store in storage:
                            if store in lhs or store in rhs:
                                results[sig].add((i, line.strip()))
            # also look for use in always blocks
            elif line.strip().startswith('always') or 'dump' in line:
                for store in storage:
                    if store in line:
                        results[sig].add((i, line.strip()))

# Additionally, look for instruction decodes
ram_instrs = ['MOVF', 'MOVFI', 'MOVFU']
instr_lines = []
for i,line in enumerate(lines):
    for mi in ram_instrs:
        if mi in line:
            instr_lines.append((i, line.strip()))

# Find any mention of signal in relevant MOV area or ram/rom/memory area
mov_leaks = []
for i, mov in instr_lines:
    # examine 10 lines before/after mov for possible sensitive use
    low = max(i-10,0)
    hi = min(i+10,len(lines))
    section = '\n'.join(lines[low:hi])
    for sig in track_signals:
        if re.search(r'\b'+re.escape(sig)+r'\b', section):
            mov_leaks.append((sig, i, mov))

# Find RAM/ROM output blocks dumped
dump_lines = [ (i,l) for i,l in enumerate(lines) if 'dump' in l or 'output' in l or 'display' in l ]
dump_mentions = []
for i,line in dump_lines:
    for sig in track_signals:
        if sig in line:
            dump_mentions.append((sig, i, line.strip()))

# Summarize
leak_summary = []
for sig,refs in results.items():
    if refs:
        leak_summary.append(f"[{sig}] references with storage/ram/output: "+str(list(refs)))
    else:
        leak_summary.append(f"[{sig}] not directly written to any obvious storage/output.")
if mov_leaks:
    leak_summary.append('Potential MOV* instruction dataflow leaks:')
    for sig,i,mov in mov_leaks:
        leak_summary.append(f"  {sig} may be involved in or near {mov} at line {i}")
if dump_mentions:
    leak_summary.append("Mentions of sensitive signal in output/display/dump lines:")
    for sig,i,line in dump_mentions:
        leak_summary.append(f"  [{sig}] at line {i}: {line}")

if not any(results.values()) and not mov_leaks and not dump_mentions:
    leak_summary.append("No direct or indirect write/leak of key[0], emode, or wrong_attmpt to storage/output/dump or RAM. Leakage not observed.")
    leak_summary.append("To recover secrets, one needs to try brute-force/key guessing, side-channel, or exploit architectural vulnerabilities.\n")

print('\n'.join(leak_summary))

