# Generate the required shellcode bytes for testing key[0]=0x00..0x10
# Instruction encodings from challenge comments

def encode_MOVI(regidx, imm):
    return bytes([0x80 | (regidx & 0xF), imm & 0xFF])
def encode_ENT():
    return bytes([0x40])
def encode_MOVFS(ram_idx, safe_rom_idx):
    return bytes([0xA0 | (ram_idx & 0xF), 0x80 | (safe_rom_idx & 0x7F)])
def encode_DUMP(ram_idx):
    return bytes([0xC0 | (ram_idx & 0x3F)])
def encode_HALT():
    return bytes([0xE0])

sc = b''
for key in range(0x00, 0x11+1):
    sc += encode_MOVI(0, key)
    sc += encode_ENT()
    sc += encode_MOVFS(255, 0)  # should encode to (..., 0x8F, 0x80)
    sc += encode_DUMP(255)
sc += encode_HALT()

# output
with open('shellcode_test_keys.bin','wb') as f:
    f.write(sc)
